-- composition of rule kernels common_subexpressions x statistics_propagation (duckdb), template graft_union
WITH RECURSIVE rc(c0) AS (SELECT 1 UNION ALL SELECT r.c0 + 1 FROM rc AS r WHERE r.c0 < 5) SELECT LIST_HAS_ALL (ARRAY[a1.c0], CASE WHEN TRUE THEN ARRAY_REVERSE (ARRAY[a1.c0]) ELSE ARRAY[1, 2, 3] END) AS c0, 'ß'::text AS c1 FROM (SELECT * FROM t1 UNION ALL SELECT * FROM t1 WHERE (SELECT count(*) FROM (SELECT 20 AS c0, a1.c5 AS c1, 'A'::text AS c2, 1000::bigint AS c3 FROM t3 AS a1 GROUP BY a1.c2, a1.c5) AS kb) < 0) AS a1;
